    {name:'DoIP', standard:'ISO 13400 / diagnostics over IP', status:'Reference only', tone:'reference', pins:'IP / Ethernet diagnostic path', text:'Carries diagnostic communication over an IP network, with vehicle discovery, connection and routing behavior.', detail:'No Ethernet discovery, routing activation, TCP or UDP vehicle endpoint is implemented.', source:5},
    {name:'LIN', standard:'ISO 17987 / local interconnect', status:'Reference only', tone:'reference', pins:'Local single-wire network', text:'A scheduled, low-cost local network, often used for simpler actuators and sensors. Its electrical layer supports rates up to 20 kbit/s.', detail:'A LIN branch is not a generic OBD scan-tool protocol. No LIN schedule or nodes run in this release.', source:6}
